	// 关闭所有旧的UI元素
	closePlayList(NULL);

	// 计算总页数
	totalPages = (fileCount + ITEMS_PER_PAGE - 1) / ITEMS_PER_PAGE;
	
	// 计算当前应该显示哪一页（包含当前播放的歌曲）
	currentPage = music_i / ITEMS_PER_PAGE;
	
