	lv_obj_set_style_radius(ui_listNextBtn, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
	lv_obj_set_style_border_width(ui_listNextBtn, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
	
	lv_obj_t *nextLabel = lv_label_create(ui_listNextBtn);
